using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using V15Voice;
public static class VoiceReportTests {
 static int count;static string root,folder;static void Check(bool yes,string text){if(!yes)throw new Exception(text);count++;Console.WriteLine("PASS "+text);}
 sealed class Engine:KokoroEngine {public double Seconds=1.8;public int Calls,FailAt,StopAt;public bool CheckFail;public override void CheckFiles(){if(CheckFail)throw new Exception("fixture missing model");}public override Wave Generate(string text,double speed,string output){Calls++;if(Calls==StopAt){Cancelled=true;throw new OperationCanceledException("fixture stop");}if(Calls==FailAt)throw new Exception("fixture generation error");ReportDevice("CPU · deterministic test fixture");int n=(int)Math.Round(Seconds/speed*24000);var samples=new short[n];for(int i=0;i<n;i++)samples[i]=i<n-1200?(short)(Math.Sin(i*.065)*6500):(short)0;return new Wave{Rate=24000,Samples=samples};}}
 static List<Cue> Cues(int n=3,double duration=2){return Enumerable.Range(1,n).Select(i=>new Cue{Id=i,Start=(i-1)*duration,End=i*duration,Text="This is test sentence number "+i+"."}).ToList();}
 static RenderOptions Options(List<Cue> c,string name){string source=Path.Combine(folder,name+".srt");File.WriteAllText(source,Scripts.ToSrt(c),Encoding.UTF8);return new RenderOptions{Locked=true,BaseSpeed=1,MinSpeed=.8,MaxSpeed=1.3,SlowShort=true,Breathing=BreathMode.None,ReportContext=new VoiceReportContext{SourcePath=source,SourceCues=VoiceRenderReport.Snapshot(c),VoiceKey="TEST:1",Description="Giọng thử rõ",UserNote="Review / kể chuyện",Styles="Kể chuyện",VoiceSource="test fixture"}};}
 static Engine New(){return new Engine{Root=root,VoiceName="Steven test fixture",DeviceMode="cpu"};}
 static string Run(List<Cue> c,Engine e,RenderOptions o,string name){return Renderer.Render(c,e,o,Path.Combine(folder,name+".wav"),(p,m)=>{});}
 static bool Fails(List<Cue> c,Engine e,RenderOptions o,string name){try{Run(c,e,o,name);return false;}catch{return true;}}
 public static int Main(){try{root=AppDomain.CurrentDomain.BaseDirectory;folder=Path.Combine(Path.GetTempPath(),"V15 báo cáo "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
  var c=Cues();var o=Options(c,"success");var e=New();e.Seconds=2.5;o.BaseSpeed=.9;string before=StateFiles.Hash(o.ReportContext.SourcePath);string wav=Run(c,e,o,"success");string text=File.ReadAllText(o.RunReport.PathName);
  Check(o.RunReport.Outcome=="THÀNH CÔNG"&&File.Exists(wav)&&o.RunReport.Wav==wav,"Success report references the actual published WAV");Check(Path.GetDirectoryName(o.RunReport.PathName)==folder&&o.RunReport.PathName.EndsWith(".voice-report.txt"),"Report saved beside Unicode source filename");Check(text.Contains("Steven test fixture")&&text.Contains("Review / kể chuyện")&&text.Contains("TEST:1"),"Voice identity and user's notes included");Check(o.RunReport.Units.Count==3&&o.RunReport.Units.All(u=>u.Before.HasValue&&u.After.HasValue&&u.Attempts.Count>=2),"Every cue has measured natural/fitted durations and speed attempts");Check(o.RunReport.Units.All(u=>Math.Abs(u.After.Value-c[u.Number-1].Actual)<.00001),"Logged fitted seconds equal actual renderer measurements");Check(text.Contains(((o.RunReport.Units[0].Speed.Value/.9-1)*100).ToString("0.000",System.Globalization.CultureInfo.InvariantCulture)+"%"),"Speed percent computed relative to 0.90 base, not relative to 1.00");Check(before==StateFiles.Hash(o.ReportContext.SourcePath),"Source SRT unchanged by reporting");
  c=Cues(2);o=Options(c,"overflow");e=New();e.Seconds=9;Check(Fails(c,e,o,"overflow")&&o.RunReport.Outcome=="THẤT BẠI"&&!File.Exists(Path.Combine(folder,"overflow.wav")),"Overflow still saves complete failure report without publishing WAV");Check(o.RunReport.Units.All(u=>u.Status=="Không khớp khung"&&u.After.HasValue),"Failed fit retains candidate measurements and failure reason");
  c=Cues();o=Options(c,"engine-error");e=New();e.FailAt=2;Check(Fails(c,e,o,"engine-error")&&File.Exists(o.RunReport.PathName),"Engine exception leaves a report");text=File.ReadAllText(o.RunReport.PathName);Check(o.RunReport.Units[1].Before==null&&text.Contains("CHƯA CHẠY TỚI")&&text.Contains("fixture generation error"),"Failed/current/unvisited cues distinguish unmeasured from zero");
  c=Cues();o=Options(c,"cancel");e=New();e.StopAt=2;Check(Fails(c,e,o,"cancel")&&o.RunReport.Outcome=="ĐÃ DỪNG"&&o.RunReport.Units[1].Before==null,"Cancellation saves partial measurements and pending rows");
  c=Cues();o=Options(c,"preflight");e=New();e.CheckFail=true;Check(Fails(c,e,o,"preflight")&&o.RunReport.Units.Count==0&&File.ReadAllText(o.RunReport.PathName).Contains("fixture missing model"),"Model/preflight failure is recorded before synthesis starts");
  c=new List<Cue>{new Cue{Id=1,Start=0,End=4,Text="This first sentence"},new Cue{Id=2,Start=4,End=8,Text="ends right here."},new Cue{Id=3,Start=8,End=12,Text="A second sentence follows."}};o=Options(c,"stages");o.Anchored=true;o.Locked=false;e=New();e.Seconds=5.8;wav=Run(c,e,o,"stages");var stage=o.RunReport.Stages.Single();Check(stage.Status=="Đạt khung chặng"&&Math.Abs(stage.After.Value-12)<.00001,"Anchored report measures the full final stage");Check(o.RunReport.Units[0].CueIds.SequenceEqual(new[]{1,2})&&o.RunReport.Units[1].CueIds.SequenceEqual(new[]{3}),"A sentence spanning cues maps to original source IDs");Check(o.RunReport.Units.All(u=>u.Before.HasValue&&!u.After.HasValue&&!u.Start.HasValue&&!u.End.HasValue),"Grouped sentence output timestamps are never fabricated by ratios");Check(stage.Attempts.Count>0&&Wave.Read(wav).Samples.Length==288000,"Anchored speed attempts logged while preserving exact final sample count");
  c=Cues(3,4);o=Options(c,"stage-stop");o.Anchored=true;o.Locked=false;e=New();e.FailAt=2;Check(Fails(c,e,o,"stage-stop")&&o.RunReport.Units.Count==3&&o.RunReport.Units[2].Status=="Chưa chạy tới"&&o.RunReport.Units[2].Before==null,"Stage plan preserves unvisited sentence after a mid-stage exception");
  c=Cues(1,3);o=Options(c,"identity-on");e=New();e.Seconds=2;string a=Run(c,e,o,"identity-on");var off=new RenderOptions{Locked=o.Locked,BaseSpeed=o.BaseSpeed,MinSpeed=o.MinSpeed,MaxSpeed=o.MaxSpeed,SlowShort=o.SlowShort,Breathing=BreathMode.None};string b=Run(Cues(1,3),new Engine{Root=root,Seconds=2},off,"identity-off");Check(StateFiles.Hash(a)==StateFiles.Hash(b),"Enabling reports does not alter generated WAV bytes");
  c=Cues(2);c[1].Text=c[0].Text;o=Options(c,"cache");e=New();e.PreviewCache=new SpeechCache();Run(c,e,o,"cache");Check(o.RunReport.Units[0].GeneratedCalls==1&&o.RunReport.Units[1].CacheCalls==1&&e.Calls==1,"Cached audio is identified without claiming it was newly synthesized");
  c=Cues(2);o=Options(c,"pauses");c[0].Text="Hello, friend.";o.ReportContext.SourceCues=VoiceRenderReport.Snapshot(c);o.Punctuation=PunctuationMode.Custom;o.CommaPause=.4;e=New();e.Seconds=.9;Run(c,e,o,"pauses");Check(o.RunReport.Units[0].PauseBefore>o.RunReport.Units[0].PauseAfter,"Custom pause compression recorded separately from speech speed");
  c=Cues(1);o=Options(c,"collision");e=New();Run(c,e,o,"collision");string first=o.RunReport.PathName,hash=StateFiles.Hash(first);o=Options(Cues(1),"collision");Run(Cues(1),New(),o,"collision");Check(o.RunReport.PathName!=first&&StateFiles.Hash(first)==hash,"Repeated renders preserve earlier reports");
  c=Cues(1);o=Options(c,"fallback");string blocker=Path.Combine(folder,"not-a-directory");File.WriteAllText(blocker,"keep");o.ReportContext.SourcePath=Path.Combine(blocker,"source.srt");wav=Run(c,New(),o,"fallback");Check(File.Exists(wav)&&File.Exists(o.RunReport.PathName)&&o.RunReport.SaveWarning.Length>0,"Report fallback does not prevent valid WAV publication");
  c=Cues(1);o=Options(c,"empty");c[0].End=-1;Check(Fails(c,New(),o,"empty")&&o.RunReport.Outcome=="THẤT BẠI","Invalid timeline gets a failure report before audio");
  c=LongText.Parse("A natural first paragraph ends here. A second sentence follows naturally.");o=Options(c,"prose-report");o.Prose=true;o.Locked=false;e=New();e.Seconds=1.2;wav=Run(c,e,o,"prose-report");Check(o.RunReport.Units.Last().GapAfter==0&&File.ReadAllText(o.RunReport.PathName).Contains("TXT · chưa có timeline nguồn"),"TXT excludes unwritten trailing gap and never invents source timestamps");for(int i=0;i<o.RunReport.Units.Count-1;i++)Check(Math.Abs(o.RunReport.Units[i].GapAfter-(o.RunReport.Units[i+1].Start.Value-o.RunReport.Units[i].End.Value))<.00001,"TXT report gap matches actual next audio position");
  var originals=new List<Cue>{new Cue{Id=1,Start=0,End=2,Text="This sentence"},new Cue{Id=2,Start=2,End=4,Text="continues right here."}};o=Options(originals,"joined");o.Locked=false;o.JoinSentences=true;e=New();var joined=SpeechGroups.Join(originals);Run(joined,e,o,"joined");Check(o.RunReport.Units.Single().CueIds.SequenceEqual(new[]{1,2}),"Legacy sentence joining retains original cue mapping in report");
  c=Cues(1);o=Options(c,"live-journal");var unfinished=new VoiceRenderReport(c,New(),o,Path.Combine(folder,"live-journal.wav"));unfinished.BeginUnit(c[0].Text);var p=new PacedSpeech();p.Parts.Add(new Wave{Rate=24000,Samples=new short[12000]});unfinished.Natural(p,.5);text=File.ReadAllText(unfinished.PathName);Check(!text.Contains("BÁO CÁO ĐÃ KẾT THÚC")&&text.Contains("đo trước căn 0.500s"),"Interrupted-process journal retains measured progress without claiming completion");
  var paths=new[]{Path.Combine(folder,"queue-fail.srt"),Path.Combine(folder,"queue-ok.srt")};foreach(string path in paths)File.WriteAllText(path,Scripts.ToSrt(Cues(1)));var jobs=paths.Select(BatchJob.Load).ToList();var reports=new List<VoiceRenderReport>();e=New();BatchRunner.Run(jobs,false,()=>false,(job,output,notify)=>{var opt=Options(job.Cues,Path.GetFileNameWithoutExtension(job.InputPath));opt.ReportContext.SourcePath=job.InputPath;e.FailAt=job.InputPath==paths[0]?e.Calls+1:0;try{return Renderer.Render(job.Cues,e,opt,output,notify);}finally{reports.Add(opt.RunReport);}},(p0,m)=>{});Check(jobs[0].State==JobState.Failed&&jobs[1].State==JobState.Done&&reports.All(r=>File.Exists(r.PathName)),"Mixed failure/success batch emits independent per-file reports");Check(reports[0].Outcome=="THẤT BẠI"&&reports[1].Outcome=="THÀNH CÔNG"&&jobs[0].Cues[0].Natural==0,"Batch checkpoint rollback does not erase the failed attempt report");
  Console.WriteLine("TOTAL VOICE REPORT "+count+" passed. Reports fixture folder: "+folder);return 0;
 }catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
